const SUBDIVISIONS: u32 = 96;

/// Drops a hailstone beside the pile every quarter second, thirty in all.
fn update(scene: &mut GameScene<'_>, _time: &FrameTime) {
    let tick = scene.add_to_counter("ticks", 1);
    if tick % 15 != 0 || scene.counter_or("hail", 0) >= 30 {
        return;
    }
    let count = scene.add_to_counter("hail", 1);
    let angle = count as f32 * 0.7;
    let transform = Transform::new([6.0 * angle.cos(), 0.3, 6.0 * angle.sin()])
        .with_scale(0.6, 0.6, 0.6);
    let stone = SphereSpawn::new().subdivisions(SUBDIVISIONS);
    scene.spawn_sphere(format!("Hail {count}"), transform, &stone);
}
